code{font:.77rem/1.8 var(--mono);color:#d2e8e3;overflow-wrap:anywhere}.worked-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:20px;padding:22px}.worked-grid span{display:block;font:.6rem var(--mono);color:var(--teal);letter-spacing:1px;margin-bottom:7px}.worked-grid strong{font:.82rem/1.7 var(--mono)}.worked-grid small{display:block;color:var(--muted);font:.7rem/1.6 var(--mono)}details summary{min-height:44px;cursor:pointer;padding:12px 20px;font-size:.86rem}details summary:hover{color:var(--teal)}.worked details{border-top:1px solid var(--edge)}.worked details p{font-size:.83rem;color:var(--muted);margin:0;padding:10px 20px 20px}.model-details{margin:20px 0 45px}.model-copy{display:grid;grid-template-columns:1fr 1fr;gap:0 30px;padding:0 20px 20px}.model-copy p{font-size:.8rem;color:var(--muted)}.model-copy strong{color:var(--text)}.sources{grid-column:1/-1}.sources a{display:inline-block;padding:8px 0}.footer{display:flex;flex-wrap:wrap;gap:16px;justify-content:space-between;border-top:1px solid var(--edge);max-width:1440px;margin:auto;padding:25px 4%;font:.6rem/1.8 var(--mono);color:var(--muted)}.footer a{min-height:44px;display:inline-flex;align-items:center}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}.fallback{padding:25px;border:1px solid var(--amber);margin-bottom:20px}
