diff --git a/tests/kalman.test.cjs b/tests/kalman.test.cjs
new file mode 100644
index 0000000000000000000000000000000000000000..1695421b792c1a291951e6a6b19b8cecccc5f68a
--- /dev/null
+++ b/tests/kalman.test.cjs
@@ -0,0 +1,68 @@
+const { test } = require('node:test');
+const assert = require('node:assert/strict');
+const M = require('../kalman/model.js');
+const near = (a,b,tol=1e-10) => assert.ok(Math.abs(a-b)<tol, `${a} != ${b}`);
+test('exact predict/correct fixture uses velocity cross covariance and Joseph correction', () => {
+  const prior = M.predict([0,0], [[1,0],[0,1]], 1, 0, 0);
+  assert.deepEqual(prior, {x:[0,0],P:[[2,1],[1,1]]});
+  const state = M.correct(prior,3,1);
+  near(state.x[0],2);near(state.x[1],1);
+  near(state.K[0],2/3);near(state.K[1],1/3);
+  for(const [i,j,value] of [[0,0,2/3],[0,1,1/3],[1,0,1/3],[1,1,2/3]]) near(state.P[i][j],value);
+});
+test('Q is discrete held-acceleration covariance q B B transpose', () => {
+  const p=M.predict([2,3],[[0,0],[0,0]],.2,4,.09);
+  near(p.x[0],2.68);near(p.x[1],3.8);
+  near(p.P[0][0],.09*.2**4/4);near(p.P[0][1],.09*.2**3/2);near(p.P[1][1],.09*.2**2);
+});
+test('dropout is exactly prediction-only and grows depth uncertainty', () => {
+  const data=M.generate({scenario:'dropout'}),rows=M.estimate(data);
+  assert.equal(rows.filter(r=>r.t>=20&&r.t<36&&r.z!==null).length,0);
+  assert.equal(rows.filter(r=>r.t>=20&&r.t<36).length,80);
+  for(const row of rows.filter(r=>r.t>=20&&r.t<36)) {assert.deepEqual(row.x,row.prior.x);assert.deepEqual(row.P,row.prior.P);assert.equal(row.innovation,null);}
+  assert.ok(rows[179].P[0][0]>rows[99].P[0][0]*10);
+  assert.ok(rows[180].P[0][0]<rows[179].P[0][0]);
+});
+test('seed replay is deterministic; tuning never changes truth, commands or fixes', () => {
+  const a=M.generate(),b=M.generate({q:.15,r:16});assert.deepEqual(a,b);
+  assert.deepEqual(M.estimate(a),M.estimate(M.generate()));
+  assert.notDeepEqual(M.generate({seed:43}),a);
+  const tuned=M.estimate(a,{q:.15,r:16});assert.notDeepEqual(tuned,M.estimate(a));
+  assert.deepEqual(tuned.map(r=>[r.z,r.u,r.truth]),M.estimate(a).map(r=>[r.z,r.u,r.truth]));
+});
+test('truth is never consumed by the filter', () => {
+  const data=M.generate(),other=data.map(r=>({...r,truth:[123456,-987]}));
+  assert.deepEqual(M.estimate(data).map(r=>[r.x,r.P,r.K]),M.estimate(other).map(r=>[r.x,r.P,r.K]));
+});
+test('scenario disturbances are explicit, bounded in time, and preserve random draws', () => {
+  const nominal=M.generate(),bias=M.generate({scenario:'bias'}),drop=M.generate({scenario:'dropout'}),current=M.generate({scenario:'current'});
+  bias.forEach((r,i)=>{assert.deepEqual(r.truth,nominal[i].truth);if(i)near(r.z-nominal[i].z,r.t>=20?2:0);});
+  drop.forEach((r,i)=>{assert.deepEqual(r.truth,nominal[i].truth);if(r.t<20||r.t>=36)assert.equal(r.z,nominal[i].z);});
+  current.filter(r=>r.t<20).forEach((r,i)=>assert.deepEqual(r,nominal[i]));
+  assert.ok(current.at(-1).truth[0]-nominal.at(-1).truth[0]>20);
+});
+test('covariance stays finite, symmetric and positive semidefinite over 100000 steps', () => {
+  for(const [q,r]of [[.0001,.01],[.0064,.64],[.16,16],[0,1]]) {
+    let s={x:[7,.1],P:[[1,0],[0,.04]]};
+    for(let i=0;i<25000;i++){
+      const p=M.predict(s.x,s.P,.2,Math.cos(i)*.1,q);s=M.correct(p,i%500<100?null:10+Math.sin(i),r);
+      assert.ok(s.x.every(Number.isFinite));assert.ok(s.P.flat().every(Number.isFinite));
+      near(s.P[0][1],s.P[1][0]);assert.ok(s.P[0][0]>=0&&s.P[1][1]>=0);
+      assert.ok(s.P[0][0]*s.P[1][1]-s.P[0][1]**2>=-1e-10);
+    }
+  }
+});
+test('seed 42 nominal has meaningful fixed RMSE; mismatch need not improve', () => {
+  const scores=Object.fromEntries(['nominal','dropout','current','bias'].map(s=>[s,M.metrics(M.estimate(M.generate({scenario:s})))]));
+  assert.ok(scores.nominal.sensor>.6&&scores.nominal.sensor<1);
+  assert.ok(scores.nominal.filter<scores.nominal.sensor);
+  assert.ok(scores.nominal.dead>scores.nominal.filter);
+  assert.equal(scores.nominal.steps,300);assert.equal(scores.dropout.fixes,220);
+  assert.ok(scores.bias.coverage<90);assert.ok(scores.current.filter>scores.nominal.filter);
+  console.log('Actual seed-42 scores:',JSON.stringify(scores));
+});
+test('RMSE handles no samples, missing fixes and differing denominators honestly', () => {
+  assert.equal(M.metrics(M.estimate(M.generate()).slice(0,1)).filter,null);
+  const r={x:[3,0],truth:[1,0],dead:[5,0],P:[[1,0],[0,1]],z:null};
+  const m=M.metrics([r,r]);assert.equal(m.sensor,null);near(m.filter,2);near(m.dead,4);assert.equal(m.fixes,0);assert.equal(m.coverage,0);
+});

diff --git a/kalman/app.js b/kalman/app.js
new file mode 100644
index 0000000000000000000000000000000000000000..1c4119410544d02db561094df617e24663559c81
--- /dev/null
+++ b/kalman/app.js
@@ -0,0 +1,206 @@
+/* UI owns playback; all physics and estimation live in model.js. */
+(() => {
+  'use strict';
+  const M = window.AbyssModel, $ = id => document.getElementById(id);
+  let config = { ...M.DEFAULTS }, data, rows, index = 0, running = false, baseline = null;
+  let timer = null, lastTime = 0, accumulator = 0;
+  const fmt = (n, digits = 2) => n === null ? '—' : n.toFixed(digits);
+  const colors = { truth: '#edf7f1', sensor: '#ffd18b', filter: '#60e1c1', dead: '#bbb0f4' };
+  const descriptions = {
+    nominal: 'Random disturbances, unbiased fixes. The default Q and R match the actual noise.',
+    dropout: 'Fixes disappear from 20–36 s. Prediction continues; uncertainty grows until correction resumes.',
+    current: 'An unknown +0.045 m/s² acceleration acts from 20–40 s. The filter must adapt to a wrong motion model.',
+    bias: 'Fixes shift +2 m after 20 s. A confident filter can follow the biased sensor and still be wrong.'
+  };
+  function announce(text) { $('announcement').textContent = text; }
+  function stop() {
+    running = false; cancelAnimationFrame(timer); timer = null;
+    $('play').textContent = index === M.STEPS ? '✓ Mission complete' : index ? '▶ Resume mission' : '▶ Start mission';
+    $('mission-state').textContent = index === M.STEPS ? 'MISSION COMPLETE' : 'READY / PAUSED';
+  }
+  function readConfig() {
+    if (!$('seed').checkValidity()) { $('seed').reportValidity(); return null; }
+    return { seed: Number($('seed').value), scenario: $('scenario').value,
+      sensorSigma: Number($('sensor-noise').value), accelSigma: Number($('accel-noise').value),
+      r: Number((10 ** Number($('r-noise').value)).toPrecision(4)),
+      q: Number((10 ** Number($('q-noise').value)).toPrecision(4)) };
+  }
+  function labels() {
+    $('sensor-value').textContent = `${config.sensorSigma.toFixed(1)} m`;
+    $('accel-value').textContent = `${config.accelSigma.toFixed(2)} m/s²`;
+    $('r-value').textContent = `${config.r.toPrecision(3)} m²`;
+    $('q-value').textContent = `${config.q.toPrecision(3)} (m/s²)²`;
+    $('scenario-help').textContent = descriptions[config.scenario];
+    $('clear-baseline').hidden = !baseline;
+    $('baseline-row').hidden = !baseline;
+    $('pin').textContent = baseline ? '＋ Replace saved baseline' : '＋ Save tuning as baseline';
+    $('baseline-note').textContent = baseline
+      ? `Baseline: R ${baseline.config.r.toPrecision(3)} m², q ${baseline.config.q.toPrecision(3)} (m/s²)². Purple trace; identical data, scored over the same elapsed steps.`
+      : 'Save a baseline, change R or q, then run again to compare.';
+  }
+  function rebuild(regenerate = false) {
+    stop(); index = 0; accumulator = 0;
+    if (regenerate || !data) data = M.generate(config);
+    rows = M.estimate(data, config);
+    $('summary').hidden = true;
+    labels(); render();
+  }
+  function changeSettings() {
+    const next = readConfig(); if (!next) return;
+    const worldChanged = ['seed', 'scenario', 'sensorSigma', 'accelSigma'].some(k => next[k] !== config[k]);
+    config = next;
+    if (worldChanged) baseline = null;
+    rebuild(worldChanged);
+    announce(worldChanged ? 'New real-world mission. Paused at zero; baseline cleared.' : 'New tuning. Same measurement stream, paused at zero; baseline retained.');
+  }
+  function advance() {
+    if (index >= M.STEPS) return;
+    index++; render();
+    if (index === M.STEPS) { stop(); debrief(); announce('Mission complete. Results are available in the mission debrief.'); }
+  }
+  function frame(now) {
+    if (!running) return;
+    accumulator += Math.min((now - lastTime) / 1000, 0.25) * Number($('speed').value);
+    lastTime = now;
+    while (accumulator >= M.DT && index < M.STEPS) { accumulator -= M.DT; advance(); }
+    if (running) timer = requestAnimationFrame(frame);
+  }
+  $('play').addEventListener('click', () => {
+    if (running) { stop(); render(); announce('Mission paused.'); return; }
+    if (index >= M.STEPS) return;
+    running = true; lastTime = performance.now();
+    $('play').textContent = 'Ⅱ Pause mission'; $('mission-state').textContent = 'MISSION IN PROGRESS';
+    announce('Mission started.'); timer = requestAnimationFrame(frame);
+  });
+  $('step').addEventListener('click', () => { stop(); advance(); if (index < M.STEPS) { render(); announce(`Stepped to ${rows[index].t.toFixed(1)} seconds. ${rows[index].event}.`); } });
+  function rewind() { rebuild(false); announce('Mission reset. Same data and tuning.'); }
+  $('reset').addEventListener('click', rewind); $('again').addEventListener('click', rewind);
+  $('replay').addEventListener('click', () => { const next = readConfig(); if (!next) return; changeSettings(); announce(`Replaying seed ${config.seed}. Mission paused at zero.`); });
+  for (const id of ['scenario', 'sensor-noise', 'accel-noise', 'r-noise', 'q-noise', 'seed']) $(id).addEventListener('change', changeSettings);
+  for (const id of ['sensor-noise', 'accel-noise', 'r-noise', 'q-noise']) $(id).addEventListener('input', changeSettings);
+  $('pin').addEventListener('click', () => {
+    stop(); baseline = { config: { ...config }, rows: M.estimate(data, config) }; labels(); render();
+    announce('Baseline saved. Change assumed R or q, then replay the same data.');
+  });
+  $('clear-baseline').addEventListener('click', () => { baseline = null; labels(); render(); announce('Baseline cleared.'); });
+  document.addEventListener('visibilitychange', () => { if (document.hidden && running) { stop(); render(); } });
+  function telemetry(id, n, unit) { $(id).replaceChildren(document.createTextNode(`${fmt(n)} `)); const small = document.createElement('small'); small.textContent = unit; $(id).appendChild(small); }
+  function render() {
+    const row = rows[index], half = 1.96 * Math.sqrt(row.P[0][0]), metrics = M.metrics(rows.slice(0, index + 1));
+    telemetry('true-depth', row.truth[0], 'm'); telemetry('measured-depth', row.z, 'm');
+    telemetry('estimated-depth', row.x[0], 'm'); telemetry('velocity', row.x[1], 'm/s');
+    telemetry('confidence', half, 'm'); telemetry('actual-error', row.x[0] - row.truth[0], 'm');
+    $('clock').textContent = `${row.t.toFixed(1).padStart(4, '0')} / 60.0 s`; $('progress').value = index;
+    $('stage').textContent = row.t < 20 ? '01 / GATE APPROACH' : row.t < 40 ? '02 / SLALOM TRANSECT' : '03 / BIN APPROACH';
