+    ctx.textAlign='left';ctx.font='9px Consolas, monospace';ctx.fillText('DEPTH m ↓',12,69);ctx.textAlign='right';ctx.fillText('MISSION TIME →',w-14,h-4);ctx.textAlign='left';
+    if(config.scenario !== 'nominal'){const start=X(20),end=X(config.scenario==='dropout'?36:config.scenario==='current'?40:60);ctx.fillStyle='#ffd18b08';ctx.fillRect(start,top,end-start,bottom-top);line(ctx,[[start,top],[start,bottom]],'#ffd18b55',1,[3,5]);}
+    const seen=rows.slice(0,index+1);
+    polygon(ctx,[...seen.map(r=>[X(r.t),Y(r.x[0]+1.96*Math.sqrt(r.P[0][0]))]),...seen.slice().reverse().map(r=>[X(r.t),Y(r.x[0]-1.96*Math.sqrt(r.P[0][0]))])],'#60e1c120');
