+    ctx.strokeStyle=colors.sensor;ctx.lineWidth=1;for(const r of seen){if(r.z!==null){ctx.beginPath();ctx.arc(X(r.t),Y(r.z),2,0,Math.PI*2);ctx.stroke();}}
+    line(ctx,seen.map(r=>[X(r.t),Y(r.x[0])]),colors.filter,2.4);
