+<!doctype html>
+<html lang="en">
+<head>
+  <meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
+  <meta name="description" content="Take an underwater robot through a seeded mission and discover how a Kalman filter turns noisy depth fixes into navigation.">
+  <title>ABYSS — A Kalman navigation lab</title>
