+// Run from any directory: node kalman/preview.cjs. No dependencies or backend.
+const http=require('node:http'),fs=require('node:fs'),path=require('node:path');
+const root=path.resolve(__dirname,'..'),port=Number(process.env.PORT || 8312);
+const mime={'.html':'text/html; charset=utf-8','.css':'text/css; charset=utf-8','.js':'text/javascript; charset=utf-8','.svg':'image/svg+xml','.png':'image/png','.jpg':'image/jpeg'};
+http.createServer((req,res)=>{
+  let file;
+  try { file=path.resolve(root,'.'+decodeURIComponent(new URL(req.url,'http://localhost').pathname)); } catch {res.writeHead(400).end();return;}
+  if(file!==root&&!file.startsWith(root+path.sep)){res.writeHead(403).end();return;}
+  try{if(fs.statSync(file).isDirectory())file=path.join(file,'index.html');const body=fs.readFileSync(file);res.writeHead(200,{'Content-Type':mime[path.extname(file)]||'application/octet-stream','Cache-Control':'no-store'}).end(body);}catch{res.writeHead(404).end('Not found');}
+}).listen(port,'127.0.0.1',()=>console.log(`ABYSS preview http://127.0.0.1:${port}/kalman/`));
