+    }));
+  }
+  function debrief() {
+    const m = M.metrics(rows);
+    $('summary').hidden = false;
+    $('summary-text').textContent = `Seed ${config.seed} · ${config.scenario}. ${m.fixes} fixes over ${m.steps} steps. Raw-fix RMSE ${fmt(m.sensor, 3)} m, filter ${fmt(m.filter, 3)} m, dead reckoning ${fmt(m.dead, 3)} m. Truth fell inside the assumed 95% interval on ${fmt(m.coverage, 1)}% of steps. ${config.scenario === 'bias' ? 'The biased fixes pull the estimate away from truth; narrow uncertainty does not mean accuracy.' : config.scenario === 'current' ? 'The unmodeled current challenges prediction. Increasing q may let new fixes correct it sooner.' : config.scenario === 'dropout' ? 'Without fixes the robot had only its motion model. Uncertainty grew; returning fixes restored corrections.' : 'Compare tuning on the same data to see the balance between sensor noise and motion uncertainty.'}`;
+    $('summary-compare').textContent = baseline ? `Same-data comparison: saved baseline RMSE ${fmt(M.metrics(baseline.rows).filter, 3)} m → current ${fmt(m.filter, 3)} m (R ${config.r.toPrecision(3)}, q ${config.q.toPrecision(3)}).` : 'Save this tuning as a baseline, change R or q, and replay to compare on identical measurements.';
+  }
+  function surface(id) {
