+    $('r-value').textContent = `${config.r.toPrecision(3)} m²`;
+    $('q-value').textContent = `${config.q.toPrecision(3)} (m/s²)²`;
+    $('scenario-help').textContent = descriptions[config.scenario];
+    $('clear-baseline').hidden = !baseline;
